        RelayDriverDependencies.ForTests(runner, new ScriptedTestRunner(new TestRunResult(0, "green")), sink),
        new RelayDriverOptions(CreateGitCommit: false, Resume: true));

    // Pre-seed the task directory with a status that shows stages 1-7 done
    // and stage 8 flagged, so firstStageToRun resolves to 8.
    var taskDir = Path.Combine(repo.Root, ".relay", "resume-8");
    Directory.CreateDirectory(taskDir);
    var statusEntries = RelayStages.All.Select(s =>
        s.Number < 8 ? new StageStatusEntry(s.Number, s.Name, "Done")
            : s.Number == 8 ? new StageStatusEntry(s.Number, s.Name, "Flagged", Error: "flagged")
            : new StageStatusEntry(s.Number, s.Name, "Waiting")).ToList();
    // No NEEDS-REVIEW marker — that would set firstStageToRun to 5.
    // No seals/ledger → firstStageToRun falls back to 8 via status detection.
    // We must also write a flag snapshot so flagged-work restore doesn't set
    // firstStageToRun to 1.
    // Actually, LoadResumeState detects firstStageToRun from status, so stage 8
    // flagged → firstStageToRun = 8. The redirect should change it to 7.
    // But RestoreFlaggedWorkIfNeededAsync runs BEFORE the pair check.
    // Let's test the redirect in isolation by checking that RestoreFlaggedWork
    // with firstStageToRun=8 returns 7.
    // This is a unit-test level assertion about the redirect, not a full
    // integration test, because the full driver resume path is complex.
    // For now, validate via the status/ledger after the run completes: both
    // stages 7 and 8 should appear, meaning the pair ran.
    await StageStatusRecord.WriteAsync(taskDir, statusEntries);
    // Write a ledger with the first 6 stages so LoadResumeState works.
    var ledger = new System.Text.StringBuilder();
    for (int i = 1; i <= 6; i++)
    {
        var stage = RelayStages.All[i - 1];
        ledger.AppendLine($"## Stage {i} - {stage.Name}");
        ledger.AppendLine();
        ledger.AppendLine("done");
        ledger.AppendLine();
    }
    await File.WriteAllTextAsync(Path.Combine(taskDir, "ledger.md"), ledger.ToString());

    var outcome = await driver.RunTaskAsync(repo.Root, "resume-8");
    // The run should succeed because the redirect made it re-enter at stage 7.
    Assert.Equal(RelayTaskOutcomeStatus.Committed, outcome.Status);

    var finalLedger = await File.ReadAllTextAsync(Path.Combine(taskDir, "ledger.md"));
    Assert.Contains("## Stage 7 - Review", finalLedger, StringComparison.Ordinal);
    Assert.Contains("## Stage 8 - Visual-review", finalLedger, StringComparison.Ordinal);
}

