/// <summary>
/// An <see cref="ITestRunner"/> that, when the command contains a path ending
/// in <c>/visual-review</c>, creates a dummy PNG in that directory so the
/// Visual-review stage has a render to reference via <c>view_image</c>.
/// Otherwise delegates to a <see cref="ScriptedTestRunner"/>.
/// </summary>
internal sealed class RenderCreatingTestRunner : ITestRunner
{
    private readonly ScriptedTestRunner _inner = new(new TestRunResult(0, "green"));

    public async Task<TestRunResult> RunAsync(string rootPath, string command, CancellationToken cancellationToken = default)
    {
        // Detect render commands: they contain "{outDir}" resolved to a visual-review path.
        const string marker = "/visual-review";
        var idx = command.IndexOf(marker, StringComparison.Ordinal);
        if (idx >= 0)
        {
            // Extract the render directory from the command — it's the first
            // path segment ending with /visual-review.
            var afterMarker = idx + marker.Length;
            var endIdx = command.IndexOf(' ', afterMarker);
            var dirPath = endIdx >= 0 ? command[..endIdx] : command;
            var dir = dirPath[(dirPath.LastIndexOf(' ', idx) + 1)..];
            if (!Directory.Exists(dir))
                Directory.CreateDirectory(dir);
            await File.WriteAllTextAsync(Path.Combine(dir, "main.png"), "fake-png");
            return new TestRunResult(0, "render ok");
        }
        return await _inner.RunAsync(rootPath, command, cancellationToken);
    }
}

